n = int(input())
rec = {}
for _ in range(n):
    nama, tipe, nilai = input().split()
    rec[nama] = (tipe, nilai)
for _ in range(int(input())):
    nama = input().strip()
    while nama in rec and rec[nama][0] == "CNAME":
        nama = rec[nama][1]
    print(rec[nama][1] if nama in rec else "NXDOMAIN")

import sys

baris = sys.stdin.read().split("\n")
method, target, _ = baris[0].split()
host = ""
for b in baris[1:]:
    if ":" in b:
        nama, nilai = b.split(":", 1)
        if nama.strip().lower() == "host":
            host = nilai.strip()
print(method, target.split("?")[0], host)

