import sys

jumlah = {}
for baris in sys.stdin.read().splitlines():
    if baris.strip():
        p = baris.split()[3]
        jumlah[p] = jumlah.get(p, 0) + 1
for p, n in sorted(jumlah.items(), key=lambda x: (-x[1], x[0])):
    print(p, n)
